package com.staging.sg.fraud.gateway.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.staging.sg.fraud.gateway.crypto.FraudKeyExchangeHsm;import org.jpos.iso.*;import org.jpos.iso.packager.ISO87APackager;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PermanentIsoMessageProcessorTest{FraudPlatformClient platform=mock(FraudPlatformClient.class);FraudKeyExchangeHsm hsm=mock(FraudKeyExchangeHsm.class);PermanentIsoMessageProcessor processor;
 @BeforeEach void init(){processor=new PermanentIsoMessageProcessor(new Iso8583FraudMapper(62,63,48),platform,hsm,"001","301","101","161","162","BANK_A","hsm:zmk:bank-a",96,48,63);}
 @Test void signOnAndEchoKeepSessionAccepted()throws Exception{for(String code:new String[]{"001","301"}){ISOMsg in=message("0800");in.set(70,code);ISOMsg out=processor.process(in);assertThat(out.getMTI()).isEqualTo("0810");assertThat(out.getString(39)).isEqualTo("00");}}
 @Test void takIsDeliveredOnlyAsEnvelopeUnderZmk()throws Exception{when(hsm.generateTakUnderZmk("BANK_A","hsm:zmk:bank-a")).thenReturn(new FraudKeyExchangeHsm.TakEnvelope("00112233445566778899AABBCCDDEEFF","A1B2C3","hsm:tak:42"));ISOMsg in=message("0800");in.set(70,"101");ISOMsg out=processor.process(in);assertThat(out.getString(70)).isEqualTo("161");assertThat(ISOUtil.hexString(out.getBytes(96))).isEqualTo("00112233445566778899AABBCCDDEEFF");assertThat(out.getString(48)).isEqualTo("A1B2C3");}
 @Test void scoringNeverReturnsPanOrDeclineDecision()throws Exception{var json=new ObjectMapper().createObjectNode().put("score",780).put("recommendedAction","REVIEW_IMMEDIATELY");when(platform.scorePermanentLink(anyMap())).thenReturn(json);ISOMsg in=message("0200");in.set(4,"000000001000");in.set(18,"5411");in.set(19,"504");in.set(22,"010");in.set(37,"REF000000001");in.set(49,"504");in.set(62,"tok_network_1");ISOMsg out=processor.process(in);assertThat(out.getString(39)).isEqualTo("00");assertThat(out.getString(63)).contains("MODE=ALERT_ONLY");assertThat(out.hasField(2)).isFalse();}
 private ISOMsg message(String mti)throws Exception{ISOMsg m=new ISOMsg();m.setPackager(new ISO87APackager());m.setMTI(mti);m.set(7,"0815030100");m.set(11,"000001");return m;}}
